import {loadFrame,lightNetwork} from './frame-cache.js';
const pending=new Map();
export async function hydrateMedia(item){if(item.previewFrames?.length)return item;if(item.archive)return item;const cached=pending.get(item.id);if(cached&&Date.now()-cached.at<120000)return {...item,...await cached.promise};
 const promise=(async()=>{const response=await fetch('/api/inventory/item?id='+encodeURIComponent(item.id));if(response.ok){const data=await response.json();return {previewFrames:data.item?.previewFrames??[],thumbnail:item.thumbnail??data.item?.thumbnail}}if(response.status===404&&/^\d+$/.test(item.equipType??'')){const r=await fetch('inventory/'+item.equipType+'.json');if(r.ok){const data=await r.json(),saved=data.items?.find(i=>i.id===item.id);return {previewFrames:saved?.previewFrames??[],thumbnail:item.thumbnail??saved?.thumbnail}}}if(response.status!==404)throw Error('原图资料暂不可用，请重试');return {}})();pending.set(item.id,{at:Date.now(),promise});if(pending.size>80)pending.delete(pending.keys().next().value);try{return {...item,...await promise}}catch(error){pending.delete(item.id);throw error}}
export function warmItem(item){if(lightNetwork())return;hydrateMedia(item).then(full=>{const src=full.previewFrames?.[0]??full.thumbnail;if(src)loadFrame(src,false).catch(()=>{})}).catch(()=>{})}
